// ─── Prisma CLI configuration ───────────────────────────────────────────────
// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
//
// Prisma 7 moved CLI configuration out of schema.prisma and into this file.
// It's the answer to "where does the connection string come from?", since the
// datasource block in schema.prisma deliberately has no `url`.

// Prisma CLI commands run as plain Node, outside Next — which loads .env for
// you. This import is what makes DATABASE_URL available below; without it,
// every migrate/generate command would fail with an undefined connection string.
import "dotenv/config";
import { defineConfig } from "prisma/config";

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    // Keeping the URL here rather than in schema.prisma means the schema file
    // holds no environment-specific detail, and the same schema works against
    // local, preview and production databases.
    url: process.env["DATABASE_URL"],
  },
});
